    enonce: "<span class=\"q\">1) </span>بيّن أنّ <span dir=\"ltr\" class=\"expr\">E = -x - y + <span class=\"frac\"><span class=\"num\">11</span><span class=\"den\">2</span></span> - 2√3</span> حيث <span dir=\"ltr\" class=\"expr\">E = |-4 + √3| + 4 - [√3 + (-y + 5 - <span class=\"frac\"><span class=\"num\">9</span><span class=\"den\">4</span></span>)] + <span class=\"frac\"><span class=\"num\">1</span><span class=\"den\">3</span></span> - (x + 4 - √3) - 2y + <span class=\"frac\"><span class=\"num\">47</span><span class=\"den\">12</span></span> - √3</span><br><span class=\"q\">2) </span>بيّن أنّ <span dir=\"ltr\" class=\"expr\">E = -x - y + <span class=\"frac\"><span class=\"num\">11</span><span class=\"den\">2</span></span> - 2√3</span> حيث احسب E إذا كان <span dir=\"ltr\" class=\"expr\">y = -x</span> علما أنّ <span dir=\"ltr\" class=\"expr\">E = -x - y + <span class=\"frac\"><span class=\"num\">11</span><span class=\"den\">2</span></span> - 2√3</span><br><span class=\"q\">3) </span>بيّن أنّ <span dir=\"ltr\" class=\"expr\">E = -x - y + <span class=\"frac\"><span class=\"num\">11</span><span class=\"den\">2</span></span> - 2√3</span> حيث احسب E إذا كان <span dir=\"ltr\" class=\"expr\">y = -x</span> علما أنّ أوجد y إذا كان <span dir=\"ltr\" class=\"expr\">E = 0</span> و <span dir=\"ltr\" class=\"expr\">x = |1 - √3|</span> <span dir=\"ltr\" class=\"expr\">E = -x - y + <span class=\"frac\"><span class=\"num\">11</span><span class=\"den\">2</span></span> - 2√3</span><br><span class=\"q\">4) </span>بيّن أنّ <span dir=\"ltr\" class=\"expr\">E = -x - y + <span class=\"frac\"><span class=\"num\">11</span><span class=\"den\">2</span></span> - 2√3</span> حيث احسب E إذا كان <span dir=\"ltr\" class=\"expr\">y = -x</span> علما أنّ أوجد y إذا كان <span dir=\"ltr\" class=\"expr\">E = 0</span> و <span dir=\"ltr\" class=\"expr\">x = |1 - √3|</span> إذا علمت أنّ <span dir=\"ltr\" class=\"expr\">|E - 3| = 3</span> <span dir=\"ltr\" class=\"expr\">E = -y + <span class=\"frac\"><span class=\"num\">13</span><span class=\"den\">2</span></span> - 3√3</span>",
    correction: [{"quoi":"","math":"<b>1)</b>"},{"quoi":"نحدّد إشارة ما بداخل القيمة المطلقة","math":"<span dir=\"ltr\" class=\"expr\">-4 + √3</span> عدد سالب تقريبا يساوي <span dir=\"ltr\" class=\"expr\">-2.27</span>"},{"quoi":"نزيل القيمة المطلقة","math":"<span dir=\"ltr\" class=\"expr\">|-4 + √3| = 4 - √3</span>"},{"quoi":"نزيل الأقواس و المعقوفات","math":"<span dir=\"ltr\" class=\"expr\">E = 4 - √3 + 4 - √3 + y - 5 + <span class=\"frac\"><span class=\"num\">9</span><span class=\"den\">4</span></span> + <span class=\"frac\"><span class=\"num\">1</span><span class=\"den\">3</span></span> - x - 4 + √3 - 2y + <span class=\"frac\"><span class=\"num\">47</span><span class=\"den\">12</span></span> - √3</span>"},{"quoi":"نجمع الحدود المتشابهة","math":"نجمع الأعداد الناطقة معا و الأعداد الصمّاء معا"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr\">E = -x - y + <span class=\"frac\"><span class=\"num\">11</span><span class=\"den\">2</span></span> - 2√3</span>"},{"quoi":"","math":"<b>2)</b>"},{"quoi":"نستعمل الشكل المختصر","math":"<span dir=\"ltr\" class=\"expr\">E = -x - y + <span class=\"frac\"><span class=\"num\">11</span><span class=\"den\">2</span></span> - 2√3</span>"},{"quoi":"نعوّض","math":"<span dir=\"ltr\" class=\"expr\">E = -x - (-x) + <span class=\"frac\"><span class=\"num\">11</span><span class=\"den\">2</span></span> - 2√3</span>"},{"quoi":"نزيل القوس","math":"<span dir=\"ltr\" class=\"expr\">E = -x + <span class=\"frac\"><span class=\"num\">11</span><span class=\"den\">2</span></span> - 2√3 + x</span>"},{"quoi":"نجمع الحدود المتشابهة","math":"نجمع الأعداد الناطقة مع بعضها و الأعداد الصمّاء مع بعضها"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr\">E = <span class=\"frac\"><span class=\"num\">11</span><span class=\"den\">2</span></span> - 2√3</span>"},{"quoi":"","math":"<b>3)</b>"},{"quoi":"نحسب x","math":"<span dir=\"ltr\" class=\"expr\">|1 - √3| = -1 + √3</span>"},{"quoi":"نعوّض x في E","math":"<span dir=\"ltr\" class=\"expr\">E = -y + <span class=\"frac\"><span class=\"num\">13</span><span class=\"den\">2</span></span> - 3√3</span>"},{"quoi":"نكتب المعادلة","math":"<span dir=\"ltr\" class=\"expr\">-y + <span class=\"frac\"><span class=\"num\">13</span><span class=\"den\">2</span></span> - 3√3 = 0</span>"},{"quoi":"نعزل y","math":"<span dir=\"ltr\" class=\"expr\">-y = 0 - (<span class=\"frac\"><span class=\"num\">13</span><span class=\"den\">2</span></span> - 3√3)</span>"},{"quoi":"نحسب الطرف الثاني","math":"<span dir=\"ltr\" class=\"expr\">0 - (<span class=\"frac\"><span class=\"num\">13</span><span class=\"den\">2</span></span> - 3√3) = -<span class=\"frac\"><span class=\"num\">13</span><span class=\"den\">2</span></span> + 3√3</span>"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr\">y = <span class=\"frac\"><span class=\"num\">13</span><span class=\"den\">2</span></span> - 3√3</span>"},{"quoi":"","math":"<b>4)</b>"},{"quoi":"القاعدة","math":"من أجل r موجب، <span dir=\"ltr\" class=\"expr\">|X| = r</span> يعني <span dir=\"ltr\" class=\"expr\">X = r</span> أو <span dir=\"ltr\" class=\"expr\">X = -r ؛</span> و إذا كان r سالبا فلا حلّ"},{"quoi":"نكتب ما بداخل القيمة المطلقة","math":"<span dir=\"ltr\" class=\"expr\">E - 3 = -y + <span class=\"frac\"><span class=\"num\">7</span><span class=\"den\">2</span></span> - 3√3</span>"},{"quoi":"الحالة الأولى","math":"<span dir=\"ltr\" class=\"expr\">-y + <span class=\"frac\"><span class=\"num\">7</span><span class=\"den\">2</span></span> - 3√3 = 3</span>"},{"quoi":"الحلّ الأوّل","math":"<span dir=\"ltr\" class=\"expr\">y = <span class=\"frac\"><span class=\"num\">1</span><span class=\"den\">2</span></span> - 3√3</span>"},{"quoi":"الحالة الثانية","math":"<span dir=\"ltr\" class=\"expr\">-y + <span class=\"frac\"><span class=\"num\">7</span><span class=\"den\">2</span></span> - 3√3 = -3</span>"},{"quoi":"الحلّ الثاني","math":"<span dir=\"ltr\" class=\"expr\">y = <span class=\"frac\"><span class=\"num\">13</span><span class=\"den\">2</span></span> - 3√3</span>"},{"quoi":"النتيجة","math":"للمعادلة حلاّن اثنان"}],
