    correction: [{"quoi":"","math":"<b>1)</b>"},{"quoi":"نختصر الطرف الأوّل","math":"<span dir=\"ltr\" class=\"expr\">-√2 + [-√2 + (-√2 + 3)] - [-<span class=\"frac\"><span class=\"num\">1</span><span class=\"den\">4</span></span> + x - x] - x - <span class=\"frac\"><span class=\"num\">5</span><span class=\"den\">4</span></span> + 4√2 = -x + 2 + √2</span>"},{"quoi":"نكتب المعادلة المختصرة","math":"<span dir=\"ltr\" class=\"expr\">-x + 2 + √2 = -1</span>"},{"quoi":"نعزل x","math":"<span dir=\"ltr\" class=\"expr\">-x = -1 - (2 + √2)</span>"},{"quoi":"نحسب الطرف الثاني","math":"<span dir=\"ltr\" class=\"expr\">-1 - (2 + √2) = -3 - √2</span>"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr\">x = 3 + √2</span>"},{"quoi":"","math":"<b>2)</b>"},{"quoi":"نختصر الطرف الأوّل","math":"<span dir=\"ltr\" class=\"expr\">[-√3 - <span class=\"frac\"><span class=\"num\">1</span><span class=\"den\">3</span></span>] + [<span class=\"frac\"><span class=\"num\">8</span><span class=\"den\">5</span></span> - (3 - <span class=\"frac\"><span class=\"num\">7</span><span class=\"den\">3</span></span> + <span class=\"frac\"><span class=\"num\">7</span><span class=\"den\">6</span></span>)] - <span class=\"frac\"><span class=\"num\">2</span><span class=\"den\">3</span></span> + y + <span class=\"frac\"><span class=\"num\">29</span><span class=\"den\">10</span></span> + 2√3 = y + <span class=\"frac\"><span class=\"num\">5</span><span class=\"den\">3</span></span> + √3</span>"},{"quoi":"نكتب المعادلة المختصرة","math":"<span dir=\"ltr\" class=\"expr\">y + <span class=\"frac\"><span class=\"num\">5</span><span class=\"den\">3</span></span> + √3 = -<span class=\"frac\"><span class=\"num\">5</span><span class=\"den\">2</span></span> - √3</span>"},{"quoi":"نعزل y","math":"<span dir=\"ltr\" class=\"expr\">y = -<span class=\"frac\"><span class=\"num\">5</span><span class=\"den\">2</span></span> - √3 - (<span class=\"frac\"><span class=\"num\">5</span><span class=\"den\">3</span></span> + √3)</span>"},{"quoi":"نحسب الطرف الثاني","math":"<span dir=\"ltr\" class=\"expr\">-<span class=\"frac\"><span class=\"num\">5</span><span class=\"den\">2</span></span> - √3 - (<span class=\"frac\"><span class=\"num\">5</span><span class=\"den\">3</span></span> + √3) = -<span class=\"frac\"><span class=\"num\">25</span><span class=\"den\">6</span></span> - 2√3</span>"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr\">y = -<span class=\"frac\"><span class=\"num\">25</span><span class=\"den\">6</span></span> - 2√3</span>"},{"quoi":"","math":"<b>3)</b>"},{"quoi":"نختصر الطرف الأوّل","math":"<span dir=\"ltr\" class=\"expr\">(a - √5 - a) - [<span class=\"frac\"><span class=\"num\">5</span><span class=\"den\">2</span></span> + (<span class=\"frac\"><span class=\"num\">3</span><span class=\"den\">2</span></span> - <span class=\"frac\"><span class=\"num\">1</span><span class=\"den\">2</span></span> + <span class=\"frac\"><span class=\"num\">7</span><span class=\"den\">3</span></span>)] + <span class=\"frac\"><span class=\"num\">1</span><span class=\"den\">2</span></span> - a + <span class=\"frac\"><span class=\"num\">29</span><span class=\"den\">6</span></span> + 2√5 = -a - <span class=\"frac\"><span class=\"num\">1</span><span class=\"den\">2</span></span> + √5</span>"},{"quoi":"نكتب المعادلة المختصرة","math":"<span dir=\"ltr\" class=\"expr\">-a - <span class=\"frac\"><span class=\"num\">1</span><span class=\"den\">2</span></span> + √5 = <span class=\"frac\"><span class=\"num\">7</span><span class=\"den\">6</span></span></span>"},{"quoi":"نعزل a","math":"<span dir=\"ltr\" class=\"expr\">-a = <span class=\"frac\"><span class=\"num\">7</span><span class=\"den\">6</span></span> - (-<span class=\"frac\"><span class=\"num\">1</span><span class=\"den\">2</span></span> + √5)</span>"},{"quoi":"نحسب الطرف الثاني","math":"<span dir=\"ltr\" class=\"expr\"><span class=\"frac\"><span class=\"num\">7</span><span class=\"den\">6</span></span> - (-<span class=\"frac\"><span class=\"num\">1</span><span class=\"den\">2</span></span> + √5) = <span class=\"frac\"><span class=\"num\">5</span><span class=\"den\">3</span></span> - √5</span>"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr\">a = -<span class=\"frac\"><span class=\"num\">5</span><span class=\"den\">3</span></span> + √5</span>"},{"quoi":"","math":"<b>4)</b>"},{"quoi":"نختصر الطرف الأوّل","math":"<span dir=\"ltr\" class=\"expr\">-<span class=\"frac\"><span class=\"num\">8</span><span class=\"den\">3</span></span> - [-4 - (2 - 1 + <span class=\"frac\"><span class=\"num\">5</span><span class=\"den\">2</span></span>)] + <span class=\"frac\"><span class=\"num\">2</span><span class=\"den\">5</span></span> + √2 + b - <span class=\"frac\"><span class=\"num\">41</span><span class=\"den\">6</span></span> = b - <span class=\"frac\"><span class=\"num\">8</span><span class=\"den\">5</span></span> + √2</span>"},{"quoi":"نكتب المعادلة المختصرة","math":"<span dir=\"ltr\" class=\"expr\">b - <span class=\"frac\"><span class=\"num\">8</span><span class=\"den\">5</span></span> + √2 = <span class=\"frac\"><span class=\"num\">4</span><span class=\"den\">3</span></span></span>"},{"quoi":"نعزل b","math":"<span dir=\"ltr\" class=\"expr\">b = <span class=\"frac\"><span class=\"num\">4</span><span class=\"den\">3</span></span> - (-<span class=\"frac\"><span class=\"num\">8</span><span class=\"den\">5</span></span> + √2)</span>"},{"quoi":"نحسب الطرف الثاني","math":"<span dir=\"ltr\" class=\"expr\"><span class=\"frac\"><span class=\"num\">4</span><span class=\"den\">3</span></span> - (-<span class=\"frac\"><span class=\"num\">8</span><span class=\"den\">5</span></span> + √2) = <span class=\"frac\"><span class=\"num\">44</span><span class=\"den\">15</span></span> - √2</span>"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr\">b = <span class=\"frac\"><span class=\"num\">44</span><span class=\"den\">15</span></span> - √2</span>"}],
