    correction: [{"quoi":"","math":"<b>1)</b>"},{"quoi":"القاعدة","math":"علامة الطرح أمام قوس تغيّر إشارة كلّ حدّ داخله، و علامة الجمع تُبقيها"},{"quoi":"نزيل الأقواس و المعقوفات","math":"<span dir=\"ltr\" class=\"expr\">M = a - a + 2 + b - <span class=\"frac\"><span class=\"num\">1</span><span class=\"den\">2</span></span> + 3 - <span class=\"frac\"><span class=\"num\">7</span><span class=\"den\">2</span></span> + 2 + 2a + 2b - 4 - √2</span>"},{"quoi":"نرتّب الحدود المتشابهة","math":"<span dir=\"ltr\" class=\"expr\">M = (a - a + 2a) + (b + 2b) + (2 - <span class=\"frac\"><span class=\"num\">1</span><span class=\"den\">2</span></span> + 3 - <span class=\"frac\"><span class=\"num\">7</span><span class=\"den\">2</span></span> + 2 - 4) - √2</span>"},{"quoi":"نجمع كلّ صنف","math":"نجمع الحدود من نفس الطبيعة، و العدد الأصمّ يُعامل كحرف"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr\">M = 2a + 3b - 1 - √2</span>"},{"quoi":"","math":"<b>2)</b>"},{"quoi":"القاعدة","math":"علامة الطرح أمام قوس تغيّر إشارة كلّ حدّ داخله، و علامة الجمع تُبقيها"},{"quoi":"نزيل الأقواس و المعقوفات","math":"<span dir=\"ltr\" class=\"expr\">N = -3 + b - b + b + <span class=\"frac\"><span class=\"num\">5</span><span class=\"den\">3</span></span> - <span class=\"frac\"><span class=\"num\">4</span><span class=\"den\">3</span></span> + a + 1 - <span class=\"frac\"><span class=\"num\">2</span><span class=\"den\">3</span></span> + 2a + b + <span class=\"frac\"><span class=\"num\">4</span><span class=\"den\">3</span></span> - π</span>"},{"quoi":"نرتّب الحدود المتشابهة","math":"<span dir=\"ltr\" class=\"expr\">N = (a + 2a) + (b - b + b + b) + (-3 + <span class=\"frac\"><span class=\"num\">5</span><span class=\"den\">3</span></span> - <span class=\"frac\"><span class=\"num\">4</span><span class=\"den\">3</span></span> + 1 - <span class=\"frac\"><span class=\"num\">2</span><span class=\"den\">3</span></span> + <span class=\"frac\"><span class=\"num\">4</span><span class=\"den\">3</span></span>) - π</span>"},{"quoi":"نجمع كلّ صنف","math":"نجمع الحدود من نفس الطبيعة، و العدد الأصمّ يُعامل كحرف"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr\">N = 3a + 2b - 1 - π</span>"},{"quoi":"","math":"<b>3)</b>"},{"quoi":"نترجم المعطى","math":"عددان متقابلان مجموعهما منعدم<span dir=\"ltr\" class=\"expr\">: M + N = 0</span>"},{"quoi":"نجمع الشكلين المختصرين","math":"<span dir=\"ltr\" class=\"expr\">M + N = 5a + 5b - 2 - √2 - π</span>"},{"quoi":"نكتب المعادلة","math":"<span dir=\"ltr\" class=\"expr\">5a + 5b - 2 - √2 - π = 0</span>"},{"quoi":"نعزل حدود الحرفين","math":"<span dir=\"ltr\" class=\"expr\">5a + 5b = 2 + √2 + π</span>"},{"quoi":"نقسم على المعامل","math":"<span dir=\"ltr\" class=\"expr\">a + b = <span class=\"frac\"><span class=\"num\">2</span><span class=\"den\">5</span></span> + <span class=\"frac\"><span class=\"num\">1</span><span class=\"den\">5</span></span> √2 + <span class=\"frac\"><span class=\"num\">1</span><span class=\"den\">5</span></span> π</span>"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr\">a + b = <span class=\"frac\"><span class=\"num\">2</span><span class=\"den\">5</span></span> + <span class=\"frac\"><span class=\"num\">1</span><span class=\"den\">5</span></span> √2 + <span class=\"frac\"><span class=\"num\">1</span><span class=\"den\">5</span></span> π</span>"},{"quoi":"","math":"<b>4)</b>"},{"quoi":"نترجم المعطى","math":"متساويان يعني أنّ فرقهما منعدم<span dir=\"ltr\" class=\"expr\">: M - N = 0</span>"},{"quoi":"نطرح الشكلين المختصرين","math":"<span dir=\"ltr\" class=\"expr\">M - N = -a + b - √2 + π</span>"},{"quoi":"نكتب المعادلة","math":"<span dir=\"ltr\" class=\"expr\">-a + b - √2 + π = 0</span>"},{"quoi":"نعزل حدود الحرفين","math":"<span dir=\"ltr\" class=\"expr\">-a + b = √2 - π</span>"},{"quoi":"نقسم على المعامل","math":"<span dir=\"ltr\" class=\"expr\">a - b = -√2 + π</span>"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr\">a - b = -√2 + π</span>"}],
