    enonce: "<span class=\"q\">1) </span>بيّن أنّ <span dir=\"ltr\" class=\"expr\">M = -a + <span class=\"frac\"><span class=\"num\">8</span><span class=\"den\">3</span></span> + √2</span> حيث <span dir=\"ltr\" class=\"expr\">M = (3 + 1 + √2) - [-√2 + (-2 + a)] + (-a + 9) + a - <span class=\"frac\"><span class=\"num\">37</span><span class=\"den\">3</span></span> - √2</span><br><span class=\"q\">2) </span>بيّن أنّ <span dir=\"ltr\" class=\"expr\">M = -a + <span class=\"frac\"><span class=\"num\">8</span><span class=\"den\">3</span></span> + √2</span> حيث أوجد a إذا علمت أنّ <span dir=\"ltr\" class=\"expr\">|M + 1| = 2</span> علما أنّ <span dir=\"ltr\" class=\"expr\">M = -a + <span class=\"frac\"><span class=\"num\">8</span><span class=\"den\">3</span></span> + √2</span><br><span class=\"q\">3) </span>بيّن أنّ <span dir=\"ltr\" class=\"expr\">M = -a + <span class=\"frac\"><span class=\"num\">8</span><span class=\"den\">3</span></span> + √2</span> حيث أوجد a إذا علمت أنّ <span dir=\"ltr\" class=\"expr\">|M + 1| = 2</span> علما أنّ أوجد b إن أمكن ذلك، إذا علمت أنّ <span dir=\"ltr\" class=\"expr\"><span class=\"frac\"><span class=\"num\">4</span><span class=\"den\">3</span></span> - |b| = <span class=\"frac\"><span class=\"num\">23</span><span class=\"den\">6</span></span></span><br><span class=\"q\">4) </span>بيّن أنّ <span dir=\"ltr\" class=\"expr\">M = -a + <span class=\"frac\"><span class=\"num\">8</span><span class=\"den\">3</span></span> + √2</span> حيث أوجد a إذا علمت أنّ <span dir=\"ltr\" class=\"expr\">|M + 1| = 2</span> علما أنّ أوجد b إن أمكن ذلك، إذا علمت أنّ أوجد <span dir=\"ltr\" class=\"expr\">|a|</span> <span dir=\"ltr\" class=\"expr\">M + 5 = √3</span> <span dir=\"ltr\" class=\"expr\">M = -a + <span class=\"frac\"><span class=\"num\">8</span><span class=\"den\">3</span></span> + √2</span>",
    correction: [{"quoi":"","math":"<b>1)</b>"},{"quoi":"القاعدة","math":"علامة الطرح أمام قوس تغيّر إشارة كلّ حدّ داخله، و علامة الجمع تُبقيها"},{"quoi":"نزيل الأقواس و المعقوفات","math":"<span dir=\"ltr\" class=\"expr\">M = 3 + 1 + √2 + √2 + 2 - a - a + 9 + a - <span class=\"frac\"><span class=\"num\">37</span><span class=\"den\">3</span></span> - √2</span>"},{"quoi":"نرتّب الحدود المتشابهة","math":"<span dir=\"ltr\" class=\"expr\">M = (-a - a + a) + (3 + 1 + 2 + 9 - <span class=\"frac\"><span class=\"num\">37</span><span class=\"den\">3</span></span>) + (√2 + √2 - √2)</span>"},{"quoi":"نجمع كلّ صنف","math":"نجمع الحدود من نفس الطبيعة، و العدد الأصمّ يُعامل كحرف"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr\">M = -a + <span class=\"frac\"><span class=\"num\">8</span><span class=\"den\">3</span></span> + √2</span>"},{"quoi":"","math":"<b>2)</b>"},{"quoi":"القاعدة","math":"من أجل r موجب، <span dir=\"ltr\" class=\"expr\">|X| = r</span> يعني <span dir=\"ltr\" class=\"expr\">X = r</span> أو <span dir=\"ltr\" class=\"expr\">X = -r ؛</span> و إذا كان r سالبا فلا حلّ"},{"quoi":"نكتب ما بداخل القيمة المطلقة","math":"<span dir=\"ltr\" class=\"expr\">M + 1 = -a + <span class=\"frac\"><span class=\"num\">11</span><span class=\"den\">3</span></span> + √2</span>"},{"quoi":"الحالة الأولى","math":"<span dir=\"ltr\" class=\"expr\">-a + <span class=\"frac\"><span class=\"num\">11</span><span class=\"den\">3</span></span> + √2 = 2</span>"},{"quoi":"الحلّ الأوّل","math":"<span dir=\"ltr\" class=\"expr\">a = <span class=\"frac\"><span class=\"num\">5</span><span class=\"den\">3</span></span> + √2</span>"},{"quoi":"الحالة الثانية","math":"<span dir=\"ltr\" class=\"expr\">-a + <span class=\"frac\"><span class=\"num\">11</span><span class=\"den\">3</span></span> + √2 = -2</span>"},{"quoi":"الحلّ الثاني","math":"<span dir=\"ltr\" class=\"expr\">a = <span class=\"frac\"><span class=\"num\">17</span><span class=\"den\">3</span></span> + √2</span>"},{"quoi":"النتيجة","math":"للمعادلة حلاّن اثنان"},{"quoi":"","math":"<b>3)</b>"},{"quoi":"نعزل القيمة المطلقة","math":"<span dir=\"ltr\" class=\"expr\"><span class=\"frac\"><span class=\"num\">4</span><span class=\"den\">3</span></span> - <span class=\"frac\"><span class=\"num\">23</span><span class=\"den\">6</span></span> = -<span class=\"frac\"><span class=\"num\">5</span><span class=\"den\">2</span></span></span>"},{"quoi":"نصل إلى المعادلة","math":"نصل إلى <span dir=\"ltr\" class=\"expr\">|b| = -<span class=\"frac\"><span class=\"num\">5</span><span class=\"den\">2</span></span></span>"},{"quoi":"نقارن بالصفر","math":"<span dir=\"ltr\" class=\"expr\">-<span class=\"frac\"><span class=\"num\">5</span><span class=\"den\">2</span></span></span> أصغر من الصفر"},{"quoi":"القاعدة","math":"القيمة المطلقة لعدد حقيقي لا تكون سالبة أبدا"},{"quoi":"النتيجة","math":"لا يوجد أيّ حلّ"},{"quoi":"","math":"<b>4)</b>"},{"quoi":"نكتب المعادلة","math":"<span dir=\"ltr\" class=\"expr\">-a + <span class=\"frac\"><span class=\"num\">23</span><span class=\"den\">3</span></span> + √2 = √3</span>"},{"quoi":"نعزل a","math":"<span dir=\"ltr\" class=\"expr\">a = <span class=\"frac\"><span class=\"num\">23</span><span class=\"den\">3</span></span> + √2 - √3</span>"},{"quoi":"نحدّد الإشارة","math":"العدد <span dir=\"ltr\" class=\"expr\"><span class=\"frac\"><span class=\"num\">23</span><span class=\"den\">3</span></span> + √2 - √3</span> هو عدد موجب تقريبا يساوي 7.35"},{"quoi":"القاعدة","math":"القيمة المطلقة لعدد موجب هي هو نفسه، و لعدد سالب هي مقابله"},{"quoi":"النتيجة","math":"<span dir=\"ltr\" class=\"expr\">|a| = <span class=\"frac\"><span class=\"num\">23</span><span class=\"den\">3</span></span> + √2 - √3</span>"}],
